import { clamp, smooth } from '../../common/math';
import type { SongHanConfig } from '../../config';

/* [swingController] state machine quay cầu, phát event swingStart / swingOpen / swingClosed / stateChange */
export const SWING_STATES = ['CLOSED', 'STOP_TRAFFIC', 'UNLOCK', 'ROTATING_OPEN', 'OPEN', 'ROTATING_CLOSE', 'LOCK', 'REOPEN_TRAFFIC'] as const;
export type SwingState = typeof SWING_STATES[number];
export type Signal = 'green' | 'amber' | 'red';

/* Vận tốc góc hình thang: tăng dần – đều – giảm dần (a = phần thời gian tăng/giảm tốc) */
function trapezoidEase(u: number, a = 0.22) {
  u = clamp(u, 0, 1); const vmax = 1 / (1 - a);
  if (u < a) return vmax * u * u / (2 * a);
  if (u < 1 - a) return vmax * (u - a / 2);
  return 1 - vmax * (1 - u) * (1 - u) / (2 * a);
}
export class SwingController extends EventTarget {
  cfg: SongHanConfig;
  state: SwingState = 'CLOSED';
  t = 0;
  speed = 30;                     // hệ số tăng tốc so với thời gian thật
  angle = 0; lift = 0; pin = 1; barrier = 0;
  signal: Signal = 'green';
  closeAsked = false;
  fromTour = false;               // quay do Tour kích hoạt: đóng ngay khi tàu buồm qua hết luồng
  spanClear: () => boolean = () => true;
  canClose: () => boolean = () => true;
  canStart: () => boolean = () => true;     // thời tiết (bão) gán predicate; false → start() từ chối và phát 'swingBlocked'

  constructor(cfg: SongHanConfig) {
    super();
    this.cfg = cfg;
  }
  get busy() { return this.state !== 'CLOSED'; }
  get allowEntry() { return this.state === 'CLOSED' || (this.state === 'REOPEN_TRAFFIC' && this.signal === 'green'); }
  start(speed?: number) {
    if (this.state !== 'CLOSED') return false;
    if (!this.canStart()) { this.dispatchEvent(new Event('swingBlocked')); return false; }
    if (speed) this.speed = speed;
    this.go('STOP_TRAFFIC'); this.dispatchEvent(new Event('swingStart'));
    return true;
  }
  requestClose() { if (this.state === 'OPEN') this.closeAsked = true; }
  go(s: SwingState) {
    this.state = s; this.t = 0;
    if (s === 'OPEN') this.closeAsked = false;
    this.dispatchEvent(new CustomEvent<SwingState>('stateChange', { detail: s }));
    if (s === 'OPEN') this.dispatchEvent(new Event('swingOpen'));
    if (s === 'CLOSED') this.dispatchEvent(new Event('swingClosed'));
  }
  update(dt: number) {
    if (this.state === 'CLOSED') return;
    const T = this.cfg.timing, rot = Math.PI / 2 * this.cfg.rotateDir;
    this.t += dt * this.speed;
    const k = (d: number) => clamp(this.t / d, 0, 1);
    switch (this.state) {
      case 'STOP_TRAFFIC':
        this.signal = this.t < T.amber ? 'amber' : 'red';
        this.barrier = smooth(clamp((this.t - T.amber) / T.barrier, 0, 1));
        if (this.t > T.amber + T.barrier && (this.spanClear() || this.t > T.stopMax)) this.go('UNLOCK');
        break;
      case 'UNLOCK': {            // rút chốt rồi nâng nhẹ nhịp khỏi gối đầu cánh
        const u = k(T.unlock);
        this.pin = 1 - smooth(clamp(u * 2, 0, 1)); this.lift = smooth(clamp(u * 2 - 1, 0, 1)) * this.cfg.lift;
        if (u >= 1) this.go('ROTATING_OPEN');
        break;
      }
      case 'ROTATING_OPEN':
        this.angle = trapezoidEase(k(T.rotate)) * rot;
        if (k(T.rotate) >= 1) this.go('OPEN');
        break;
      case 'OPEN':
        if ((this.t > T.openHold || this.closeAsked) && this.canClose()) this.go('ROTATING_CLOSE');
        break;
      case 'ROTATING_CLOSE':
        this.angle = (1 - trapezoidEase(k(T.rotate))) * rot;
        if (k(T.rotate) >= 1) { this.angle = 0; this.go('LOCK'); }
        break;
      case 'LOCK': {              // hạ nhịp xuống gối rồi đẩy chốt khóa
        const u = k(T.lock);
        this.lift = (1 - smooth(clamp(u * 2, 0, 1))) * this.cfg.lift; this.pin = smooth(clamp(u * 2 - 1, 0, 1));
        if (u >= 1) this.go('REOPEN_TRAFFIC');
        break;
      }
      case 'REOPEN_TRAFFIC':
        this.barrier = 1 - smooth(k(T.barrier));
        this.signal = this.t >= T.barrier ? 'green' : 'red';
        if (this.t > T.barrier + 2) { this.barrier = 0; this.signal = 'green'; this.go('CLOSED'); }
        break;
    }
  }
}

# Dù lượn ban đêm: cầu tự xoay, rồng tự phun — Kế hoạch triển khai

> **For agentic workers:** REQUIRED SUB-SKILL: Use superpowers:subagent-driven-development (recommended) or superpowers:executing-plans to implement this plan task-by-task. Steps use checkbox (`- [ ]`) syntax for tracking.

**Goal:** Khi đang bay dù và trời là đêm, Cầu sông Hàn tự xoay lặp lại và Cầu Rồng tự phun lửa, nước; ban đêm ngoài dù và ban ngày không tự chạy.

**Architecture:** Một module nhỏ `src/explore/nightShows.ts` được gọi mỗi bước bay từ `advance()`. Nó chỉ bật `show.on` và điều khiển `SwingController` có sẵn, không thêm hình học hay UI. `swingUI.ts` có hai điều kiện chặn để camera không bị kéo đi và lịch 23:00 không chạy khi bay.

**Tech Stack:** Vite 6, TypeScript 5.9, three@0.165, test Chromium qua `tests/lib.mjs`.

**Spec:** [2026-11-09-du-luon-hieu-ung-dem-design.md](../specs/2026-11-09-du-luon-hieu-ung-dem-design.md)

## Global Constraints

- Làm trên nhánh `feature/du-luon-hieu-ung-dem`, không commit thẳng `main`. Tin nhắn commit kết thúc bằng dòng `Co-Authored-By` theo cấu hình phiên.
- Không thêm thư viện, ảnh, đèn, mesh; không có khóa i18n mới.
- Không thêm/bớt `rand()` lúc dựng scene, không đổi thứ tự `build*()`.
- Số mới nằm ở `CONFIG.explore`, chú thích tiếng Việt, đơn vị, `(ước lượng)`.
- Comment tiếng Việt, tiền tố hàm `ex*`.
- Chạy `npm run typecheck` sau mọi thay đổi `.ts`. Các test đọc `dist/`, nên build trước khi test.
- Bộ test nặng chỉ chạy một lần ở Task 3. Trước đó kiểm không còn tiến trình `*-check.mjs` / `drawcalls.mjs` mồ côi.

## Review Focus

1. Vào dù khi cầu đang quay 1× (từ lịch 23:00, hoặc đã mở): cầu tăng lên 30× và đóng xong như thường — test 6f.
2. Bão vừa hết trong lúc nghỉ hoặc lúc chờ: lượt mới bắt đầu, không kẹt và không phát `swingBlocked` lặp — test 6d.
3. Sang ngày khi cầu đang mở và tàu chưa qua: cầu chờ tàu rồi đóng, không có lượt mới — test 6c.
4. Bấm Đêm rồi Ngày liên tục: không có lượt thứ hai khi trời đang là ngày, `show.on` luôn theo trời — test 6c (không lượt mới), 6a/6b (`show.on`).
5. Trong suốt lượt quay người chơi vẫn lái được dù, `cam.mode` không rời `'glider'` — test 6b.

---

### Task 1: Bộ tự chạy ban đêm và chặn kéo camera

**Files:**
- Create: `src/explore/nightShows.ts`
- Modify: `src/config.ts` (trong `exploreBase`), `src/explore/index.ts`, `src/main.ts:96`, `src/ui/swingUI.ts:44`
- Test: `tests/explore-check.mjs` (mục 6, thêm trước `} catch (e) {` ở cuối file)

**Interfaces:**
- Produces:
  - `exNight: { enabled: boolean; rest: number; show: typeof show }` — `enabled` bật/tắt bộ tự chạy, `rest` là số giây nghỉ còn lại, `show` là tham chiếu để test đọc.
  - `exNightBind(ctrl: SwingController): void`
  - `exNightStep(dt: number): void`
  - `setupExplore(ctrl: SwingController): void` (đổi chữ ký)
  - `window.__app.explore.nightShows === exNight`
  - `CONFIG.explore.nightShows: { swingSpeed: number; swingRest: number }`, đọc mỗi bước, không chụp lại vào hằng số, vì test đổi giá trị lúc chạy.

- [ ] **Step 1: Tạo nhánh**

Run: `git switch -c feature/du-luon-hieu-ung-dem`
Expected: đang ở nhánh mới. Spec và plan chưa commit đi theo nhánh này.

- [ ] **Step 2: Viết test thất bại — mục 6 trong `tests/explore-check.mjs`**

Test rút ngắn thời gian bằng cách đổi config thành `swingSpeed = 600`, `swingRest = 0.2`, vì SwiftShader chạy chậm và `dt` bị chặn ở 0,05 s.

