1	import * as THREE from 'three';
2	import { CONFIG } from '../../config';
3	import { scene } from '../../core/renderer';
4	import { pScale, windFx, weatherFx } from '../../core/shared';
5	import { fireLight } from '../../core/lights';
6	import { rand, lerp } from '../../common/math';
7	import { t as tr } from '../../i18n';
8	import { headGroup, whiskerGroup, MOUTH_LOCAL } from './head';
9	
10	/* ============================ Lửa & nước ============================ */
11	const particleVert = `attribute float aSize; attribute float aAlpha; attribute vec3 aColor; uniform float uScale;
12	  varying float vA; varying vec3 vC;
13	  void main(){ vC = aColor; vA = aAlpha; vec4 mv = modelViewMatrix * vec4(position, 1.0);
14	    gl_PointSize = aSize * uScale / max(-mv.z, 0.5); gl_Position = projectionMatrix * mv; }`;
15	const particleFrag = `varying float vA; varying vec3 vC;
16	  void main(){ float r = length(gl_PointCoord - 0.5); float a = smoothstep(0.5, 0.0, r); a *= a;
17	    gl_FragColor = vec4(vC, a * vA);
18	    #include <tonemapping_fragment>
19	    #include <colorspace_fragment>
20	  }`;
21	
22	interface Particles {
23	  n: number; pos: Float32Array; vel: Float32Array; col: Float32Array; size: Float32Array; alpha: Float32Array;
24	  life: Float32Array; max: Float32Array; kind: Uint8Array; next: number; acc: number; points?: THREE.Points;
25	  idle: boolean;   // khung trước không còn hạt sống và buffer đã ghi 0 ⇒ khi không phun thì bỏ vòng lặp + upload (D-018)
26	}
27	function makeParticles(n: number, blending: THREE.Blending): Particles {
28	  const g = new THREE.BufferGeometry();
29	  const sys: Particles = { n, pos: new Float32Array(n * 3), vel: new Float32Array(n * 3), col: new Float32Array(n * 3), size: new Float32Array(n), alpha: new Float32Array(n), life: new Float32Array(n), max: new Float32Array(n), kind: new Uint8Array(n), next: 0, acc: 0, idle: false };
30	  g.setAttribute('position', new THREE.BufferAttribute(sys.pos, 3).setUsage(THREE.DynamicDrawUsage));
31	  g.setAttribute('aColor', new THREE.BufferAttribute(sys.col, 3).setUsage(THREE.DynamicDrawUsage));
32	  g.setAttribute('aSize', new THREE.BufferAttribute(sys.size, 1).setUsage(THREE.DynamicDrawUsage));
33	  g.setAttribute('aAlpha', new THREE.BufferAttribute(sys.alpha, 1).setUsage(THREE.DynamicDrawUsage));
34	  const mat = new THREE.ShaderMaterial({ uniforms: { uScale: pScale }, vertexShader: particleVert, fragmentShader: particleFrag, transparent: true, depthWrite: false, blending, toneMapped: blending !== THREE.AdditiveBlending });
35	  sys.points = new THREE.Points(g, mat); sys.points.frustumCulled = false;
36	  scene.add(sys.points);
37	  return sys;
38	}
39	let fire: Particles, waterJet: Particles;
40	export function createFire() { fire = makeParticles(CONFIG.fireCount, THREE.AdditiveBlending); }
41	export function createWaterJet() { waterJet = makeParticles(CONFIG.waterCount, THREE.NormalBlending); }
42	
43	/* vị trí miệng rồng (thế giới) — âm thanh trình diễn to nhỏ theo khoảng cách camera tới đây */
44	export const mouthW = new THREE.Vector3();
45	const fwd = new THREE.Vector3();
46	function upload(s: Particles) {
47	  const a = s.points.geometry.attributes;
48	  a.position.needsUpdate = a.aColor.needsUpdate = a.aSize.needsUpdate = a.aAlpha.needsUpdate = true;
49	}
50	function emit(sys: Particles, count: number, init: (s: Particles, i: number) => void) {
51	  for (let c = 0; c < count; c++) { const i = sys.next; sys.next = (sys.next + 1) % sys.n; init(sys, i); }
52	}
53	
54	/* Trình diễn phun lửa (9 lần) rồi phun nước, lặp theo CONFIG.showCycle */
55	export const show = { on: false, t: 0, fireOn: false, waterOn: false, key: 'sOff', args: null as Record<string, number> | null };
56	export const showLabel = () => tr(show.key, show.args);
57	export function updateShow(dt: number) {
58	  if (!show.on) { show.fireOn = show.waterOn = false; show.key = 'sOff'; show.args = null; return; }
59	  if (!weatherFx.showAllowed) { show.fireOn = show.waterOn = false; show.key = 'sWeather'; show.args = null; return; }   // mưa to / gió mạnh / bão: tạm dừng, show.on (nút người dùng) giữ nguyên
60	  show.t = (show.t + dt) % CONFIG.showCycle;
61	  const t = show.t;
62	  show.fireOn = t < 27 && (t % 3) < 1.6;
63	  show.waterOn = t >= 27 && t < 42;
64	  if (t < 27) { show.key = 'sFire'; show.args = { n: Math.floor(t / 3) + 1 }; }
65	  else if (t < 42) { show.key = 'sWater'; show.args = null; }
66	  else { show.key = 'sRest'; show.args = { s: Math.ceil(CONFIG.showCycle - t) }; }
67	}
68	export function updateEffects(dt: number, time: number) {
69	  headGroup.updateMatrixWorld();
70	  mouthW.copy(MOUTH_LOCAL).applyMatrix4(headGroup.matrixWorld);
71	  fwd.set(1, 0, 0).applyQuaternion(headGroup.quaternion);
72	  const W = CONFIG.weather.wind, windOn = windFx.x !== 0 || windFx.z !== 0;   // gió thời tiết (mặc định 0: không đổi gì, không thêm rand())
73	  // Lửa
74	  if (show.fireOn) {
75	    fire.acc += dt * 520; const n = Math.floor(fire.acc); fire.acc -= n;
76	    emit(fire, n, (s, i) => {
77	      const sp = 18 + rand() * 9;
78	      s.pos[i * 3] = mouthW.x + rand() - 0.5; s.pos[i * 3 + 1] = mouthW.y + rand() - 0.5; s.pos[i * 3 + 2] = mouthW.z + rand() - 0.5;
79	      s.vel[i * 3] = fwd.x * sp + (rand() - 0.5) * 4; s.vel[i * 3 + 1] = fwd.y * sp + 1.5 + (rand() - 0.5) * 4; s.vel[i * 3 + 2] = (rand() - 0.5) * 4;
80	      s.life[i] = 0; s.max[i] = 0.45 + rand() * 0.55;
81	    });
82	  }
83	  const fireRun = show.fireOn || !fire.idle; let live = 0;
84	  for (let i = 0; fireRun && i < fire.n; i++) {
85	    if (fire.life[i] >= fire.max[i]) { fire.alpha[i] = 0; fire.size[i] = 0; continue; }
86	    live++;
87	    fire.life[i] += dt; const t = Math.min(fire.life[i] / fire.max[i], 1), drag = 1 - 1.4 * dt;
88	    fire.vel[i * 3] *= drag; fire.vel[i * 3 + 2] *= drag; fire.vel[i * 3 + 1] = fire.vel[i * 3 + 1] * drag + 9 * dt;
89	    if (windOn) { fire.vel[i * 3] += windFx.x * W.fire * dt; fire.vel[i * 3 + 2] += windFx.z * W.fire * dt; }   // lửa bị gió đánh dạt
90	    for (let a = 0; a < 3; a++) fire.pos[i * 3 + a] += fire.vel[i * 3 + a] * dt;
91	    let r: number, g: number, b: number;
92	    if (t < 0.25) { const k = t / 0.25; r = 1; g = lerp(0.95, 0.55, k); b = lerp(0.6, 0.12, k); }
93	    else { const k = (t - 0.25) / 0.75; r = lerp(1, 0.7, k); g = lerp(0.55, 0.1, k); b = lerp(0.12, 0.03, k); }
94	    fire.col[i * 3] = r * 0.9; fire.col[i * 3 + 1] = g * 0.75; fire.col[i * 3 + 2] = b * 0.6;
95	    fire.alpha[i] = 0.55 * Math.pow(1 - t, 1.3); fire.size[i] = 1.6 + 7.5 * t;
96	  }
97	  // Nước + sương
98	  if (show.waterOn) {
99	    waterJet.acc += dt * 300; const n = Math.floor(waterJet.acc); waterJet.acc -= n;
100	    emit(waterJet, n, (s, i) => {
101	      const mist = rand() < 0.25; s.kind[i] = mist ? 1 : 0;
102	      const sp = mist ? 8 + rand() * 5 : 26 + rand() * 6;
103	      s.pos[i * 3] = mouthW.x; s.pos[i * 3 + 1] = mouthW.y; s.pos[i * 3 + 2] = mouthW.z;
104	      s.vel[i * 3] = fwd.x * sp + (rand() - 0.5) * 2.5; s.vel[i * 3 + 1] = sp * 0.42 + (rand() - 0.5) * 2.5; s.vel[i * 3 + 2] = (rand() - 0.5) * (mist ? 6 : 2.5);
105	      s.life[i] = 0; s.max[i] = mist ? 2.2 + rand() : 2.6 + rand() * 0.8;
106	    });
107	  }
108	  if (fireRun) { upload(fire); fire.idle = live === 0; }
109	  const ground = CONFIG.roadY + 0.2, waterRun = show.waterOn || !waterJet.idle; live = 0;
110	  for (let i = 0; waterRun && i < waterJet.n; i++) {
111	    if (waterJet.life[i] >= waterJet.max[i] || waterJet.pos[i * 3 + 1] < ground) { waterJet.alpha[i] = 0; waterJet.size[i] = 0; waterJet.life[i] = waterJet.max[i]; continue; }
112	    live++;
113	    waterJet.life[i] += dt; const t = waterJet.life[i] / waterJet.max[i], mist = waterJet.kind[i] === 1;
114	    const drag = 1 - (mist ? 1.2 : 0.08) * dt;
115	    waterJet.vel[i * 3] *= drag; waterJet.vel[i * 3 + 2] *= drag;
116	    waterJet.vel[i * 3 + 1] = waterJet.vel[i * 3 + 1] * drag - (mist ? 1.5 : 9.8) * dt;
117	    if (windOn) { const k = (mist ? W.mist : W.water) * dt; waterJet.vel[i * 3] += windFx.x * k; waterJet.vel[i * 3 + 2] += windFx.z * k; }   // tia nước lệch, sương bay xa theo gió
118	    for (let a = 0; a < 3; a++) waterJet.pos[i * 3 + a] += waterJet.vel[i * 3 + a] * dt;
119	    waterJet.col[i * 3] = mist ? 0.9 : 0.62; waterJet.col[i * 3 + 1] = mist ? 0.95 : 0.84; waterJet.col[i * 3 + 2] = 1.0;
