1	// Kiểm tra chế độ tự khám phá bằng dù lượn (kế hoạch feature/explore-du-luon).
2	//   Mục 1–2: mô hình bay thuần, dù, camera bám (src/explore/*) qua móc window.__app.exFlight.
3	//   Mục 3: điều phối chế độ bay, phím, ?explore=glider qua window.__app.explore.
4	//   Mục 4: màn chọn phương tiện, giao diện khi bay (body.explore), i18n 9 ngôn ngữ.
5	//   Mục 5: đo draw call và ms/khung ở 4 tư thế bay, ngày/đêm (chỉ đo; fail nếu phần dù ngày ≠ đêm).
6	//
7	//   npm run build && npm run test:explore
8	import { fileURLToPath } from 'node:url';
9	import { readFileSync } from 'node:fs';
10	import { serveDir, launch, openApp, frames, tap } from './lib.mjs';
11	
12	const problems = [];
13	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
14	
15	const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
16	const browser = await launch();
17	try {
18	  // Mục 1 — mô hình bay thuần
19	  const P = await openApp(browser, srv.url);
20	  await frames(P.page, 2);
21	  const has = await P.page.evaluate(() => !!(window.__app && window.__app.exFlight));
22	  check('có __app.exFlight', has);
