// Kiểm tra chế độ tự khám phá bằng dù lượn (kế hoạch feature/explore-du-luon).
//   Mục 1–2: mô hình bay thuần, dù, camera bám (src/explore/*) qua móc window.__app.exFlight.
//   Mục 3: điều phối chế độ bay, phím, ?explore=glider qua window.__app.explore.
//   Mục 4: màn chọn phương tiện, giao diện khi bay (body.explore), i18n 9 ngôn ngữ.
//   Mục 5: đo draw call và ms/khung ở 4 tư thế bay, ngày/đêm (chỉ đo; fail nếu phần dù ngày ≠ đêm).
//
//   npm run build && npm run test:explore
import { fileURLToPath } from 'node:url';
import { readFileSync } from 'node:fs';
import { serveDir, launch, openApp, frames, tap } from './lib.mjs';

const problems = [];
const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };

const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
const browser = await launch();
try {
  // Mục 1 — mô hình bay thuần
  const P = await openApp(browser, srv.url);
  await frames(P.page, 2);
  const has = await P.page.evaluate(() => !!(window.__app && window.__app.exFlight));
  check('có __app.exFlight', has);
  if (has) {
    const r = await P.page.evaluate(() => {
      const { exCreate, exStep, exInputFromKeys, CONFIG_explore: C } = window.__app.exFlight;
      const dt = 1 / 60, out = {};
      const run = (s, inp, sec, each) => { for (let i = 0; i < Math.round(sec * 60); i++) { exStep(s, inp, dt); if (each) each(s); } };
      // 1a tốc độ ngang không đổi
      let ok = true, last = null;
      for (const [turn, climb] of [[1, 1], [-1, -1], [1, -1], [0, 0]]) {
        const s = exCreate(); last = null;
        run(s, { turn, climb }, 30, (s) => { if (last) { const v = Math.hypot(s.pos.x - last.x, s.pos.z - last.z) / dt; if (Math.abs(v - C.speed) > 0.01) ok = false; } last = { x: s.pos.x, z: s.pos.z }; });
      }
      out.a = ok;
      // 1b rẽ trái / phải
      let s = exCreate(); let y0 = s.yaw; run(s, { turn: 1, climb: 0 }, 3); out.bL = s.yaw - y0;
      s = exCreate(); y0 = s.yaw; run(s, { turn: -1, climb: 0 }, 3); out.bR = s.yaw - y0;
      // 1c lên/xuống
      s = exCreate(); run(s, { turn: 0, climb: 1 }, 200); out.cUp = s.pos.y;
      s = exCreate(); run(s, { turn: 0, climb: -1 }, 200); out.cDown = s.pos.y;
      // 1d thả phím
      s = exCreate(); run(s, { turn: 1, climb: 0 }, 2); run(s, { turn: 0, climb: 0 }, 2.5); const yb = s.yaw; run(s, { turn: 0, climb: 0 }, 0.5);
      out.dBank = s.bank; out.dYaw = s.yaw - yb;
      // Kẹp cứng = bước mà exStep phải ép pos về đúng mép khung (pos nằm đúng trên biên); tường mềm thì không bao giờ xảy ra
      const onEdge = (s) => s.pos.x === C.bounds.x0 || s.pos.x === C.bounds.x1 || s.pos.z === C.bounds.z0 || s.pos.z === C.bounds.z1;
      const sim = (s, inp, sec) => {   // trả số bước bị kẹp, số lần bank đổi dấu trong 60 s cuối
        let clamped = 0, flips = 0, prev = 0;
        for (let i = 0; i < Math.round(sec * 60); i++) {
          exStep(s, inp, dt); if (onEdge(s)) clamped++;
          if (i >= Math.round((sec - 60) * 60)) { const sg = Math.sign(s.bank); if (sg !== 0 && prev !== 0 && sg !== prev) flips++; if (sg !== 0) prev = sg; }
        }
        return { clamped, flips };
      };
      // 1e bay thẳng 600 s, A 600 s, D 600 s từ điểm cất cánh: 0 bước kẹp
      let e = 0; for (const sp of [C.speedMin, C.speed, C.speedMax]) for (const turn of [0, 1, -1]) { const s = exCreate(); s.speed = sp; e += sim(s, { turn, climb: 0 }, 600).clamped; }
      out.e = e;
      // 1f xuất phát trong dải returnMargin, hướng ra ngoài: cách mép 150 và 300 m, 4 mép + góc (ra ngoài và dọc mép), không phím / giữ A / giữ D, 180 s
      const mx = (C.bounds.x0 + C.bounds.x1) / 2, mz = (C.bounds.z0 + C.bounds.z1) / 2, B = C.bounds;
      let fClamped = 0, fMaxFlips = 0, fCases = 0;
      for (const off of [150, 300]) {
        const starts = [[B.x1 - off, mz, 0], [B.x0 + off, mz, Math.PI], [mx, B.z0 + off, Math.PI / 2], [mx, B.z1 - off, -Math.PI / 2],
          [B.x1 - off, B.z0 + off, Math.PI / 4], [B.x1 - off, B.z0 + off, Math.PI / 2], [B.x0 + off, B.z1 - off, -3 * Math.PI / 4], [B.x0 + off, B.z1 - off, -Math.PI / 2]];
        for (const sp of [C.speedMin, C.speed, C.speedMax]) for (const [x, z, yaw] of starts) for (const turn of [0, 1, -1]) {
          const s = exCreate(); s.pos.set(x, 300, z); s.yaw = yaw; s.bank = 0; s.speed = sp;
          const r = sim(s, { turn, climb: 0 }, 180); fClamped += r.clamped; fMaxFlips = Math.max(fMaxFlips, r.flips); fCases++;
        }
      }
      out.f = fClamped; out.fFlips = fMaxFlips; out.fCases = fCases;
      // 1g phím
      const k = (...a) => exInputFromKeys(new Set(a));
      out.g = [k('a').turn === 1, k('arrowright').turn === -1, k('a', 'd').turn === 0, k('w').climb === 1, k('s', 'arrowup').climb === 0, k().turn === 0 && k().climb === 0];
      // 1i tăng/giảm tốc
      s = exCreate(); run(s, { turn: 0, climb: 0, throttle: 1 }, 10); out.iMax = s.speed; const held = s.speed; run(s, { turn: 0, climb: 0, throttle: 0 }, 2); out.iHold = s.speed === held;
      run(s, { turn: 0, climb: 0, throttle: -1 }, 10); out.iMin = s.speed;
      out.iKeys = k('e').throttle === 1 && k('q').throttle === -1 && k('q', 'e').throttle === 0 && k('a').throttle === 0;
      // 1h
      s = exCreate();
      out.h = s.pos.x === C.takeoff[0] && s.pos.y === C.takeoff[1] && s.pos.z === C.takeoff[2] && s.yaw === C.takeoffYaw && s.bank === 0;
      return out;
    });

