60	  const tourKey = TOUR_VIEWS[name];
61	  tourBox().hidden = !tourKey; document.body.classList.toggle('touring', !!tourKey);
62	  if (tourKey) { setActiveTour(tourKey); showTourCaption(0); tour.shown = 0; flyTo(activeTour.stops[0], 'tour'); return; }
63	  if (name === 'drive') { cam.mode = 'drive'; controls.enabled = false; drive.x = -700; return; }
64	  if (name === 'tpDrive') { cam.mode = 'tpDrive'; controls.enabled = false; tpDrive.x = -1300; return; }
65	  if (name === 'hrDrive') { cam.mode = 'hrDrive'; controls.enabled = false; hrDrive.x = -1000; eye.k = 1; return; }
66	  if (name === 'swRide') { enterSwRide(); return; }
67	  if (name === 'walk') { cam.mode = 'walk'; controls.enabled = false; walk.x = -240; walk.z = 17.4; walk.yaw = 0; canvas.focus(); return; }
68	  flyTo(VIEWS[name]);
69	}
70	/* Kịch bản bão nắm camera (chế độ 'storm'): bỏ chọn nút góc nhìn, tắt Tour / lái xe / đi bộ; updateCamera() đọc scenario.pose() mỗi khung */
71	export function followScenario() {
72	  dropRide();
73	  document.querySelectorAll('[data-view]').forEach((b) => b.setAttribute('aria-pressed', 'false'));
74	  document.getElementById('hint').hidden = true;
75	  tourBox().hidden = true; document.body.classList.remove('touring');
76	  controls.maxPolarAngle = Math.PI * 0.495;
77	  cam.flight.then = null; cam.mode = 'storm'; controls.enabled = false;
78	}
79	export function updateCamera(dt: number) {
80	  const flight = cam.flight;
81	  if (cam.mode !== 'hrDrive') eye.k = 1;
82	  if (cam.mode === 'fly') {
83	    flight.t += dt / flight.dur; const k = smooth(Math.min(flight.t, 1));
84	    camera.position.lerpVectors(flight.fromP, flight.toP, k); controls.target.lerpVectors(flight.fromT, flight.toT, k);
85	    camera.lookAt(controls.target);
86	    if (flight.t >= 1) { if (flight.then === 'tour') startTour(); else { cam.mode = 'orbit'; controls.enabled = true; } }
87	  } else if (cam.mode === 'tour') {
88	    updateTour(dt);
89	  } else if (cam.mode === 'swRide') {
90	    /* tư thế do SunWheel.update đặt (sau khi vòng quay quay, cùng khung hình); không gọi controls.update() */
91	  } else if (cam.mode === 'glider') {
92	    /* tư thế do explore.update đặt ngay sau updateCamera; không gọi controls.update() */
93	  } else if (cam.mode === 'storm') {
